package io.github.plrlr.autopilot.skills.evolved;

import io.github.plrlr.autopilot.plan.Option;
import io.github.plrlr.autopilot.skills.Fail;
import io.github.plrlr.autopilot.skills.FairProbe;
import net.minecraft.core.BlockPos;

import java.util.Set;

public class StoneByHand extends EvolvedSkill {
	private static final Set<String> STONE = Set.of("stone", "cobblestone", "deepslate", "cobbled_deepslate");
	private int want;
	private int base;
	private BlockPos target;
	private BlockPos pickup;
	private int pickupTicks;
	private int lastGot;
	private int lastProgress;
	private int digs;
	private int scanCooldown;

	public static Option offer(Context c) {
		if (!"collect".equals(c.lastSkill()) || !"TIMEOUT".equals(c.lastCode())) return null;
		if (Player.gameSeconds() - c.lastEndSeconds() > 150) return null;
		Option m = c.main();
		if (m == null || !"collect".equals(m.skill()) || m.arg() == null || !m.arg().startsWith("stone")) return null;
		if (Player.inWater() || Player.inLava()) return null;
		return new Option("stone_by_hand", m.arg(), "collect timed out: mine stone in reach instead");
	}

	@Override
	public String name() { return "stone_by_hand"; }

	private static int stoneCount() {
		return Math.max(Player.count("stone"), Player.count("cobblestone") + Player.count("cobbled_deepslate"));
	}

	private static String id(BlockPos p) {
		String b = Player.blockIfVisible(p);
		if (b == null) return null;
		int i = b.indexOf(':');
		return i >= 0 ? b.substring(i + 1) : b;
	}

	private static boolean isStone(BlockPos p) {
		String b = id(p);
		return b != null && STONE.contains(b);
	}

	@Override
	protected void start() {
		want = 1;
		if (arg != null) {
			String[] parts = arg.split(":");
			if (parts.length > 1) {
				try { want = Math.max(1, Integer.parseInt(parts[1])); } catch (NumberFormatException e) { want = 1; }
			}
		}
		if (Player.count("pickaxe") <= 0 && !Player.hold("pickaxe")) {
			fail(Fail.NEED_ITEM, "no pickaxe for stone");
			return;
		}
		base = stoneCount();
		lastGot = 0;
		lastProgress = 0;
	}

	private BlockPos findTarget() {
		BlockPos f = Player.feet();
		BlockPos best = null;
		double bestD = Double.MAX_VALUE;
		double r = Math.min(4.3, Player.reach());
		for (int dx = -3; dx <= 3; dx++)
			for (int dy = -1; dy <= 3; dy++)
				for (int dz = -3; dz <= 3; dz++) {
					BlockPos p = f.offset(dx, dy, dz);
					if (dx == 0 && dz == 0 && dy == -1) continue; // don't dig the floor here
					double d = Player.pos().add(0, 1.62, 0).distanceTo(p.getCenter());
					if (d > r || d >= bestD) continue;
					if (!isStone(p) || FairProbe.lavaSeenNear(p)) continue;
					best = p;
					bestD = d;
				}
		return best;
	}

	@Override
	protected void tick() {
		int got = stoneCount() - base;
		if (got >= want) { done("mined " + got + " stone in place"); return; }
		if (got != lastGot) { lastGot = got; lastProgress = ticks; }
		if (ticks - lastProgress > 20 * 25) { fail(Fail.NO_PROGRESS, "no stone gained in 25 s (got " + got + "/" + want + ")"); return; }
		if (Player.inLava()) { fail(Fail.HAZARD, "in lava"); return; }

		if (pickup != null) {
			if (++pickupTicks > 40 || Player.feet().distSqr(pickup) <= 1) {
				pickup = null;
				Player.stopWalking();
			} else {
				if (!Player.walking()) Player.walkNear(pickup, 0);
				return;
			}
		}

		if (target != null) {
			String b = id(target);
			if (b == null || !STONE.contains(b)) {
				if (b != null && (b.equals("air") || b.equals("cave_air"))) {
					pickup = target.getY() >= Player.feet().getY() - 1 ? target : null;
					pickupTicks = 0;
				}
				Player.releaseAll();
				target = null;
				return;
			}
			Player.lookAt(target);
			Player.holdBestToolFor(target);
			if (!Player.mine(target)) { Player.releaseAll(); target = null; }
			return;
		}

		if (scanCooldown > 0) { scanCooldown--; return; }
		target = findTarget();
		if (target != null) return;
		// Nothing in reach: dig straight down one block at a time.
		BlockPos below = Player.feet().below();
		if (digs < 12 && Player.onGround() && isStone(below)) {
			if (FairProbe.lavaSeenNear(below)) { fail(Fail.HAZARD, "lava next to the block below"); return; }
			digs++;
			target = below;
			return;
		}
		if (digs >= 12) { fail(Fail.NO_PROGRESS, "dug down 12 without enough stone"); return; }
		scanCooldown = 10;
		if (ticks > 20 * 6 && got == 0) fail(Fail.NOT_FOUND, "no stone within reach in sight");
	}
}
